import math
from typing import Optional

def solve_math_problem() -> int:
    """
    Finds the integer n such that n^2 = aabb = 1100a + 11b,
    where 1 <= a <= 9 and 0 <= b <= 9.

    The equation is n^2 = 11 * (100a + b).
    Since 11 is prime, n^2 must be divisible by 11, so n must be a multiple of 11.
    Let n = 11k. Then 121k^2 = 11(100a + b), which simplifies to 11k^2 = 100a + b.
    """
    for a in range(1, 10):
        for b in range(0, 10):
            number = 1100 * a + 11 * b
            root = math.isqrt(number)
            if root * root == number:
                return root
    raise ValueError("No solution found for the given constraints.")

def solve_math_problem_test(case: int) -> int:
