def solve_math_problem(
    celsius_value: float,
    c_freeze: float,
    c_boil: float,
    s_freeze: float,
    s_boil: float
) -> float:
    """
    Calculates the temperature on the SAMO scale given a Celsius value,
    assuming a linear relationship between the two scales.
    """
    if c_boil == c_freeze:
        raise ValueError("Celsius boiling and freezing points must be different.")

    try:
        # Linear interpolation formula: y = y0 + (x - x0) * (y1 - y0) / (x1 - x0)
        slope = (s_boil - s_freeze) / (c_boil - c_freeze)
        samo_value = s_freeze + (celsius_value - c_freeze) * slope
        return float(samo_value)
    except ZeroDivisionError:
        raise ValueError("Invalid scale range provided.")

